questionvariables.text:
/* (a) Binary to Gray */
b: [1, rand(2), rand(2), rand(2), rand(2), rand(2), rand(2), rand(2)];
bin_val: sconcat(b[1], b[2], b[3], b[4], b[5], b[6], b[7], b[8]);
g_res: [b[1], if b[1]=b[2] then 0 else 1, if b[2]=b[3] then 0 else 1, if b[3]=b[4] then 0 else 1, if b[4]=b[5] then 0 else 1, if b[5]=b[6] then 0 else 1, if b[6]=b[7] then 0 else 1, if b[7]=b[8] then 0 else 1];
ta1: sconcat(g_res[1], g_res[2], g_res[3], g_res[4], g_res[5], g_res[6], g_res[7], g_res[8]);

/* (b) Gray to Binary */
gray_bits: [1, rand(2), rand(2), rand(2), rand(2), rand(2), rand(2), rand(2)];
gray_val: sconcat(gray_bits[1], gray_bits[2], gray_bits[3], gray_bits[4], gray_bits[5], gray_bits[6], gray_bits[7], gray_bits[8]);
b_res: [0, 0, 0, 0, 0, 0, 0, 0];
b_res[1]: gray_bits[1];
for i: 2 thru 8 do (
  if b_res[i-1]=gray_bits[i] then b_res[i]: 0 else b_res[i]: 1
);
ta2: sconcat(b_res[1], b_res[2], b_res[3], b_res[4], b_res[5], b_res[6], b_res[7], b_res[8]);
